//! Delivery range evidence at distinct pipeline stages, not broadcast certification.
use crate::{effects::Frame,model::Project};use serde_json::{json,Value};
fn range(f:&Frame)->Value{let(mut invalid,mut transparent,mut below,mut above,mut negative_alpha,mut high_alpha)=(0u64,0u64,[0u64;3],[0u64;3],0u64,0u64);let mut lo=[f64::INFINITY;3];let mut hi=[f64::NEG_INFINITY;3];let mut n=0u64;for(i,p) in f.d.chunks_exact(4).enumerate(){if i%65536==0{crate::guard::check()}if p.iter().any(|v|!v.is_finite()){invalid+=1;continue}if p[3]<0.{negative_alpha+=1}if p[3]>1.{high_alpha+=1}if p[3]<=0.{transparent+=1;continue}n+=1;for j in 0..3{let v=p[j] as f64;lo[j]=lo[j].min(v);hi[j]=hi[j].max(v);if v<0.{below[j]+=1}if v>1.{above[j]+=1}}}json!({"visible_pixels":n,"nonfinite_pixels":invalid,"transparent_or_nonpositive_alpha_pixels":transparent,"negative_alpha_pixels":negative_alpha,"above_one_alpha_pixels":high_alpha,"min_rgb":if n>0{Some(lo)}else{None},"max_rgb":if n>0{Some(hi)}else{None},"below_zero_rgb":below,"above_one_rgb":above})}
pub fn audit(p:&Project,f:&Frame)->Result<Value,String>{let q=&p.color_pipeline;if !q.enabled{return Err("output audit requires managed working-linear project".into())}q.validate()?;if f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len()){return Err("invalid audit frame".into())}let mut params=crate::effects::Params::new();for(k,v)in[("from_gamut",q.working_gamut as f64),("to_gamut",q.output_gamut as f64),("from_transfer",0.),("to_transfer",0.),("reference_white",q.reference_white)]{params.insert(k.into(),crate::keyframe::Prop::new(v));}let working=range(f);crate::guard::reserve(f.d.len().checked_mul(std::mem::size_of::<f32>()).ok_or("audit frame size overflow")?);let mut output=Frame{w:f.w,h:f.h,d:f.d.clone()};super::managed::apply(&params,&mut output,0.)?;let linear=range(&output);let peak=if q.output_transfer==6{Some(10000./q.reference_white)}else{None};let pq_over=peak.map(|peak|output.d.chunks_exact(4).filter(|p|p[3]>0.&&p[..3].iter().any(|v|*v as f64>peak)).count());output.d.copy_from_slice(&f.d);super::pipeline::output(p,&mut output)?;let encoded=range(&output);Ok(json!({"working_linear":working,"output_gamut_linear_before_mapping":linear,"configured_encoded_output":encoded,"output_gamut":q.output_gamut,"output_transfer":q.output_transfer,"tone_map_enabled":q.tone_map,"gamut_compress_enabled":q.gamut_compress,"pq_nominal_peak_linear":peak,"above_pq10000nit_rgb_pixels_before_mapping":pq_over,"note":"Stages distinguish gamut conversion, configured mapping and encoded bounds. Linear above1 is not necessarily illegal HDR. PQ encoding bounds negatives and >10000 declared nits. RGB range audit is not YUV legal-range, broadcast compliance, HDR certification or a recommended creative change."}))}
/// Diagnostic overlay on configured SDR preview; identifies output-linear gamut excursions.
pub fn gamut_overlay(p:&Project,f:&Frame,ceiling:f64)->Result<(Frame,Value),String>{let q=&p.color_pipeline;q.validate()?;if f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len()){return Err("invalid gamut frame".into())}if !q.enabled||q.output_gamut!=0||![1,8].contains(&q.output_transfer)||!ceiling.is_finite()||!(1e-6 ..=1000.).contains(&ceiling){return Err("gamut overlay requires managed Rec709 SDR preview and positive linear ceiling".into())}super::frame::validate(f)?;crate::guard::reserve(f.d.len().checked_mul(std::mem::size_of::<f32>()).and_then(|n|n.checked_mul(2)).ok_or("gamut overlay frame size overflow")?);let mut linear=Frame{w:f.w,h:f.h,d:f.d.clone()};let mut params=crate::effects::Params::new();for(k,v)in[("from_gamut",q.working_gamut as f64),("to_gamut",q.output_gamut as f64),("from_transfer",0.),("to_transfer",0.)]{params.insert(k.into(),crate::keyframe::Prop::new(v));}super::managed::apply(&params,&mut linear,0.)?;let mut out=Frame{w:f.w,h:f.h,d:f.d.clone()};super::pipeline::output(p,&mut out)?;let(mut low,mut high,mut both)=(0u64,0u64,0u64);for(i,v)in linear.d.chunks_exact(4).enumerate(){if i%65536==0{crate::guard::check()}if v[3]<=0.{continue}let l=v[..3].iter().any(|v|*v<0.);let h=v[..3].iter().any(|v|*v as f64>ceiling);let c=if l&&h{both+=1;Some([1.,0.,1.])}else if l{low+=1;Some([0.,0.25,1.])}else if h{high+=1;Some([1.,0.,0.])}else{None};if let Some(c)=c{out.d[i*4..i*4+3].copy_from_slice(&c);out.d[i*4+3]=1.}}Ok((out,json!({"negative_only_pixels":low,"above_ceiling_only_pixels":high,"both_pixels":both,"linear_ceiling":ceiling,"legend":{"negative":"blue","above_ceiling":"red","both":"magenta"},"stage":"output gamut linear before tone/gamut mapping","note":"Excursion evidence, not proof of illegalHDR/clipping or actualdisplaycoverage. Preview background is configured SDR output."})))}
